// Snapshots meals.db into demo/lib/seed-meals.js.
//
// Run manually after changing the database:  npm run demo:seed
// This is deliberately NOT part of the demo's build — the demo must not depend
// on better-sqlite3, so the generated file is committed instead.
//
// Image columns become STATIC IMPORTS rather than strings. next/image does not
// apply basePath to a plain string src (see get-img-props.js), so a string
// would 404 under /onwards-foodies/. A static import is rewritten by webpack
// and resolves correctly.

import Database from "better-sqlite3";
import { writeFileSync, existsSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const appRoot = resolve(here, "..");
const outFile = resolve(appRoot, "demo/lib/seed-meals.js");

const db = new Database(resolve(appRoot, "meals.db"), { readonly: true });
const meals = db.prepare("SELECT * FROM meals").all();
db.close();

if (meals.length === 0) {
  console.error("[demo-seed] meals.db returned no rows — aborting");
  process.exit(1);
}

// One import per distinct image, deduplicated and given a stable identifier.
const imageIdents = new Map();
meals.forEach((meal) => {
  if (imageIdents.has(meal.image)) return;
  const file = meal.image.split("/").pop();
  const ident = `img_${file.replace(/[^a-zA-Z0-9]/g, "_")}`;
  imageIdents.set(meal.image, { ident, file });

  if (!existsSync(resolve(appRoot, "public/images", file))) {
    console.error(`[demo-seed] missing image for "${meal.slug}": ${file}`);
    process.exit(1);
  }
});

const imports = [...imageIdents.values()]
  .map(({ ident, file }) => `import ${ident} from "@/assets/meals/${file}";`)
  .join("\n");

// JSON.stringify preserves the instruction text byte-for-byte — the leading
// newline and the indentation matter, because the detail page turns \n into
// <br /> and renders the result as HTML.
const rows = meals
  .map((meal) => {
    const fields = Object.entries(meal)
      .map(([key, value]) =>
        key === "image"
          ? `    image: ${imageIdents.get(value).ident},`
          : `    ${key}: ${JSON.stringify(value)},`,
      )
      .join("\n");
    return `  {\n${fields}\n  },`;
  })
  .join("\n");

writeFileSync(
  outFile,
  `// AUTO-GENERATED by scripts/export-demo-seed.mjs — do not edit by hand.
// Regenerate with \`npm run demo:seed\` from the repository root.
${imports}

export const seedMeals = [
${rows}
];

export function getSeedMeal(slug) {
  const meal = seedMeals.find((m) => m.slug === slug);
  // Return a copy: the detail view rewrites the instructions string, and the
  // seed array is module-level state shared across every render.
  return meal ? { ...meal } : undefined;
}
`,
);

console.log(
  `[demo-seed] wrote ${meals.length} meals and ${imageIdents.size} images to demo/lib/seed-meals.js`,
);
